const BASE_URL = "https://mcstaging2.hayward.com/rest/V1/";
const HEADERS = {
  Authorization: "Bearer sukfeirw2foyx2x54uy2s6kwhwun3stt",
};

export const fetchAPI = async (data, searchCriteria = 'searchCriteria=[]') => {
    const response = await fetch(`${BASE_URL}crossreference-${data}/search?${searchCriteria}`, { headers: HEADERS }, { 
        headers: {
            Authorization: "Bearer sukfeirw2foyx2x54uy2s6kwhwun3stt",
          },
          mode: 'no-cors',
     });
    if (!response.ok) throw new Error(`Failed to fetch ${BASE_URL}crossreference-${data}/search?${searchCriteria}`);
    return response.json();
};
